<template><section><div class="title"><h1>分类影片</h1><span>PAGE {{page}}</span></div><VideoGrid :items="items"/><Pagination :page="page" :pages="pages" @change="go"/></section></template><script setup>import {ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {getCategoryVideos,normalizeList} from '../api/vod';import VideoGrid from '../components/VideoGrid.vue';import Pagination from '../components/Pagination.vue';const r=useRoute(),router=useRouter(),items=ref([]),page=ref(1),pages=ref(1);async function load(){page.value=Number(r.query.page||1);try{const x=await getCategoryVideos(r.params.id,page.value);items.value=normalizeList(x);pages.value=Number(x.pagecount||x.page||1)}catch{}}function go(n){router.push({query:{page:n}})}onMounted(load);watch(()=>r.params.id,load);watch(()=>r.query.page,load)</script>
